// loadFixture opens an in-memory DB and replays a golden per-version schema
// fixture from testdata/ (schema_v0.sql … schema_v7.sql, regenerated by
// testdata/gen_fixtures.sh). Each fixture terminates with
// `PRAGMA user_version = N;`, so db.Migrate starts at exactly rung N.
func loadFixture(t *testing.T, name string) *sql.DB {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read fixture %s: %v", name, err)
	}
	conn, err := sql.Open("sqlite", ":memory:")
	if err != nil {
		t.Fatalf("open in-memory db: %v", err)
	}
	if _, err := conn.Exec(string(raw)); err != nil {
		conn.Close()
		t.Fatalf("seed fixture %s: %v", name, err)
	}
	t.Cleanup(func() { conn.Close() })
	return conn
}

func userVersion(t *testing.T, conn *sql.DB) int {
	t.Helper()
	var v int
	if err := conn.QueryRow("PRAGMA user_version").Scan(&v); err != nil {
		t.Fatalf("read user_version: %v", err)
	}
	return v
}

func tableColumns(t *testing.T, conn *sql.DB, table string) []string {
	t.Helper()
	rows, err := conn.Query("SELECT name FROM pragma_table_info(?) ORDER BY cid", table)
	if err != nil {
		t.Fatalf("pragma_table_info(%s): %v", table, err)
	}
	defer rows.Close()
	var cols []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err != nil {
			t.Fatalf("scan column: %v", err)
		}
		cols = append(cols, name)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("pragma_table_info rows: %v", err)
	}
	return cols
}

func tableExists(t *testing.T, conn *sql.DB, name string) bool {
	t.Helper()
	var count int
	if err := conn.QueryRow(
		`SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=?`, name,
	).Scan(&count); err != nil {
		t.Fatalf("inspect for %s: %v", name, err)
	}
	return count == 1
}

// indexDefs returns "name(col,col DESC,…)" per index. indexNames compares only
// names, which a DROP+CREATE that keeps the name but changes the columns slips
// straight past — the exact drift that would leave a migrated DB and a fresh DB
// on different schemas at the same user_version. Compares pragma_index_xinfo
// rather than sqlite_master.sql because the raw DDL text differs by whitespace
// and IF NOT EXISTS between the schema and migration paths.
func indexDefs(t *testing.T, conn *sql.DB) []string {
	t.Helper()
	rows, err := conn.Query(`
		SELECT m.name, (
			SELECT group_concat(x.name || CASE WHEN x.desc THEN ' DESC' ELSE '' END)
			FROM pragma_index_xinfo(m.name) x WHERE x.key = 1
		)
		FROM sqlite_master m
		WHERE m.type = 'index' AND m.name NOT LIKE 'sqlite_%'`)
	if err != nil {
		t.Fatalf("inspect index defs: %v", err)
	}
	defer rows.Close()
	var defs []string
	for rows.Next() {
		var name string
		var cols sql.NullString
		if err := rows.Scan(&name, &cols); err != nil {
			t.Fatalf("scan index def: %v", err)
		}
		defs = append(defs, name+"("+cols.String+")")
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("index def rows: %v", err)
	}
	sort.Strings(defs)
	return defs
}

func indexNames(t *testing.T, conn *sql.DB) []string {
	t.Helper()
	rows, err := conn.Query(
		`SELECT name FROM sqlite_master WHERE type='index' AND name NOT LIKE 'sqlite_%'`,
	)
	if err != nil {
		t.Fatalf("inspect indexes: %v", err)
	}
	defer rows.Close()
	var names []string
	for rows.Next() {
		var n string
		if err := rows.Scan(&n); err != nil {
			t.Fatalf("scan index: %v", err)
		}
		names = append(names, n)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("index rows: %v", err)
	}
	sort.Strings(names)
	return names
}

