// normalizeSchemaSQL folds fresh multi-line DDL and the canonical
// ALTER-appended tails onto one whitespace-normalized form. sqlite already
// strips IF NOT EXISTS and trailing semicolons from stored text; single
// spaces inside string literals (e.g. the FTS tokenizer) are preserved by
// Fields/Join.
func normalizeSchemaSQL(s string) string {
	return strings.Join(strings.Fields(s), " ")
}

// schemaSQLSnapshot keyed (type,name) → normalized stored sql for every user
// schema object, excluding the FTS5 shadow tables (memories_fts_data/_idx/
// _content/_docsize/_config) and sqlite_autoindex rows per SM-R6. The FTS
// virtual table itself IS included — its CREATE text carries the tokenizer,
// asserted separately by the callers.
func schemaSQLSnapshot(t *testing.T, conn *sql.DB) map[[2]string]string {
	t.Helper()
	rows, err := conn.Query(`
		SELECT type, name, sql FROM sqlite_master
		WHERE sql IS NOT NULL
		  AND name NOT LIKE 'memories_fts_%'
		  AND name NOT LIKE 'sqlite_autoindex%'
	`)
	if err != nil {
		t.Fatalf("snapshot sqlite_master: %v", err)
	}
	defer rows.Close()
	out := make(map[[2]string]string)
	for rows.Next() {
		var typ, name, sqlText string
		if err := rows.Scan(&typ, &name, &sqlText); err != nil {
			t.Fatalf("scan sqlite_master row: %v", err)
		}
		out[[2]string{typ, name}] = normalizeSchemaSQL(sqlText)
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("sqlite_master rows: %v", err)
	}
	return out
}

// ftsTableSQL returns the stored CREATE VIRTUAL TABLE text for memories_fts.
func ftsTableSQL(t *testing.T, conn *sql.DB) string {
	t.Helper()
	var sqlText string
	if err := conn.QueryRow(
		`SELECT sql FROM sqlite_master WHERE type='table' AND name='memories_fts'`,
	).Scan(&sqlText); err != nil {
		t.Fatalf("read memories_fts sql: %v", err)
	}
	return sqlText
}

// TestInit_FreshMatchesMigratedShape proves SM-R6: every historical path
// vN→current (N = 0..7) converges to a schema byte-identical to fresh for all
// user objects, after whitespace normalization. It is also the ONLY guard
// against gen_fixtures.sh's inline rung SQL drifting from the Go consts — if
// the script's copy diverges, the checked-in fixture fails convergence here.
func TestInit_FreshMatchesMigratedShape(t *testing.T) {
	const porterTokenizer = "tokenize='porter unicode61 tokenchars ''_-'''"
	for _, v := range []int{0, 1, 2, 3, 4, 5, 6, 7} {
		t.Run(fmt.Sprintf("v%d", v), func(t *testing.T) {
			fresh := newTestDB(t)
			migrated := loadFixture(t, fmt.Sprintf("schema_v%d.sql", v))
			if err := db.Migrate(migrated); err != nil {
				t.Fatalf("Migrate: %v", err)
			}
			if got, want := userVersion(t, migrated), db.CurrentSchemaVersion; got != want {
				t.Errorf("post-migrate user_version = %d, want %d", got, want)
			}

			wantSnap := schemaSQLSnapshot(t, fresh)
			gotSnap := schemaSQLSnapshot(t, migrated)
			for key, wantSQL := range wantSnap {
				if gotSQL, ok := gotSnap[key]; !ok {
					t.Errorf("migrated DB missing object %v", key)
				} else if gotSQL != wantSQL {
					t.Errorf("object %v diverges:\n fresh   = %s\n migrate = %s", key, wantSQL, gotSQL)
				}
			}
			for key := range gotSnap {
				if _, ok := wantSnap[key]; !ok {
					t.Errorf("migrated DB has extra object %v not in fresh", key)
				}
			}

			// The tokenizer flip is asserted from the stored CREATE VIRTUAL
			// TABLE text, not from row counts (SM-R6).
			if fts := ftsTableSQL(t, migrated); !strings.Contains(fts, porterTokenizer) {
				t.Errorf("migrated memories_fts missing porter tokenizer:\n%s", fts)
			}
			if fts := ftsTableSQL(t, fresh); !strings.Contains(fts, porterTokenizer) {
				t.Errorf("fresh memories_fts missing porter tokenizer:\n%s", fts)
			}
		})
	}
}

// TestMigrate_V7toV8FlipsFTS proves SM-R1 on the real v7 shape: seeding the
// v7 fixture (trigram FTS + 4-column recency indexes) and running the ladder
// must land on CurrentSchemaVersion with the porter tokenizer, a row-preserving
// FTS reindex, and a no-op second Migrate. Porter stemming is proven
// behaviorally: a query for "cancellation" matches a row containing "cancel".
func TestMigrate_V7toV8FlipsFTS(t *testing.T) {
	conn := loadFixture(t, "schema_v7.sql")
	if fts := ftsTableSQL(t, conn); strings.Contains(fts, "porter") {
		t.Fatalf("v7 fixture already porter — wrong fixture shape:\n%s", fts)
	}

	now := int64(1000000)
	for _, m := range []struct {
		id, title, what, learned string
	}{
		{id: "mem_a", title: "cancel the sync job", what: "retry the sync", learned: "cancellation handling is manual"},
		{id: "mem_b", title: "port mapping", what: "host moved", learned: "check the port table first"},
	} {
		if _, err := conn.Exec(`
			INSERT INTO memories (id, session_id, task_type, kind, title, what, learned, tags, fingerprint, created_at, updated_at)
			VALUES (?, 'sess', 'crm', 'task_pattern', ?, ?, ?, '', ?, ?, ?)`,
			m.id, m.title, m.what, m.learned, "fp_"+m.id, now, now); err != nil {
			t.Fatalf("seed row %s: %v", m.id, err)
		}
	}

	if err := db.Migrate(conn); err != nil {
		t.Fatalf("Migrate: %v", err)
	}
	if got, want := userVersion(t, conn), db.CurrentSchemaVersion; got != want {
		t.Fatalf("post-migrate user_version = %d, want %d", got, want)
	}
	if fts := ftsTableSQL(t, conn); !strings.Contains(fts, "tokenize='porter unicode61 tokenchars ''_-'''") {
		t.Errorf("memories_fts not porter after v7→v8:\n%s", fts)
	}

	// Row-preserving: the rung reindexes every memories row into memories_fts.
	var ftsCount, memCount int
	if err := conn.QueryRow(`SELECT COUNT(*) FROM memories_fts`).Scan(&ftsCount); err != nil {
		t.Fatalf("count memories_fts: %v", err)
	}
	if err := conn.QueryRow(`SELECT COUNT(*) FROM memories`).Scan(&memCount); err != nil {
		t.Fatalf("count memories: %v", err)
	}
	if ftsCount != memCount {
		t.Errorf("memories_fts rows = %d, memories rows = %d (row-preserving reindex)", ftsCount, memCount)
	}

	// Porter stemmer works: "cancellation" finds the row whose learned text
	// contains "cancel" (both stem to the same token).
	var title string
	if err := conn.QueryRow(`
		SELECT m.title FROM memories_fts fts
		JOIN memories m ON m.rowid = fts.rowid
		WHERE memories_fts MATCH 'cancellation'
		ORDER BY fts.rank LIMIT 1
	`).Scan(&title); err != nil {
		t.Errorf("porter stem MATCH 'cancellation': %v", err)
	} else if title != "cancel the sync job" {
		t.Errorf("porter MATCH returned %q, want the cancel row", title)
	}

	// A second Migrate is a no-op (version gate skips the rung).
	if err := db.Migrate(conn); err != nil {
		t.Errorf("second Migrate: %v", err)
	}
}

