// The CHECK constraint must reject any origin outside {manual, auto} and accept
// 'auto' (the value an Auto-session-summary carries).
func TestOrigin_CheckConstraint(t *testing.T) {
	conn := newTestDB(t)
	if _, err := conn.Exec(`
		INSERT INTO memories (id, session_id, task_type, kind, title, what, learned, tags, fingerprint, created_at, updated_at, origin)
		VALUES ('mem_bad', 'sess', 'crm', 'task_pattern', 't', 'w', 'l', '', 'fp_bad', 1, 1, 'bogus')`,
	); err == nil {
		t.Error("expected CHECK violation for origin='bogus', got nil")
	}
	if _, err := conn.Exec(`
		INSERT INTO memories (id, session_id, task_type, kind, title, what, learned, tags, fingerprint, created_at, updated_at, origin)
		VALUES ('mem_auto', 'sess', 'claude_session', 'session_summary', 't', 'w', 'l', '', 'fp_auto', 1, 1, 'auto')`,
	); err != nil {
		t.Errorf("insert origin='auto' should succeed: %v", err)
	}
}

// hasLifecycleColumns reports whether cols contains the v6 lifecycle columns
// (ADR-0031: decay/review + pin).
func hasLifecycleColumns(cols []string) (hasReview, hasPinned bool) {
	for _, c := range cols {
		switch c {
		case "review_after":
			hasReview = true
		case "pinned":
			hasPinned = true
		}
	}
	return
}

func TestInit_FreshDBHasLifecycleColumns(t *testing.T) {
	conn := newTestDB(t)
	hasReview, hasPinned := hasLifecycleColumns(tableColumns(t, conn, "memories"))
	if !hasReview {
		t.Error("fresh DB missing memories.review_after")
	}
	if !hasPinned {
		t.Error("fresh DB missing memories.pinned")
	}
}

func TestInit_FreshDBHasArchivedMemoriesTable(t *testing.T) {
	conn := newTestDB(t)
	if !tableExists(t, conn, "archived_memories") {
		t.Error("fresh DB missing archived_memories table")
	}
}

// v5→v6 adds review_after (nullable) + pinned (default 0) without backfilling
// review_after on existing rows (D1 — grandfather NULL, never mass-flag
// legacy rows needs_review on day one).
func TestMigrate_V5toV6AddsLifecycleColumnsGrandfathersRows(t *testing.T) {
	conn := loadFixture(t, "schema_v0.sql")
	now := int64(1000000)
	if _, err := conn.Exec(`
		INSERT INTO memories (id, session_id, task_type, kind, title, what, learned, tags, fingerprint, created_at, updated_at)
		VALUES ('mem_lc', 'sess_lc', 'crm', 'task_pattern', 't', 'w', 'l', '', 'fp_lc', ?, ?)`,
		now, now); err != nil {
		t.Fatalf("seed row: %v", err)
	}
	if err := db.Migrate(conn); err != nil {
		t.Fatalf("Migrate: %v", err)
	}
	hasReview, hasPinned := hasLifecycleColumns(tableColumns(t, conn, "memories"))
	if !hasReview {
		t.Fatal("migrated DB missing memories.review_after")
	}
	if !hasPinned {
		t.Fatal("migrated DB missing memories.pinned")
	}

	var reviewAfter sql.NullInt64
	var pinned int
	if err := conn.QueryRow(`SELECT review_after, pinned FROM memories WHERE id = 'mem_lc'`).Scan(&reviewAfter, &pinned); err != nil {
		t.Fatalf("read migrated row: %v", err)
	}
	if reviewAfter.Valid {
		t.Errorf("migrated review_after = %v, want NULL (D1 — no backfill)", reviewAfter)
	}
	if pinned != 0 {
		t.Errorf("migrated pinned = %d, want 0", pinned)
	}
	if !tableExists(t, conn, "archived_memories") {
		t.Error("migrated DB missing archived_memories table")
	}
	if got, want := userVersion(t, conn), db.CurrentSchemaVersion; got != want {
		t.Errorf("post-migrate user_version = %d, want %d", got, want)
	}
}

// assertColumnParity is the D5/SM-R8 archived_memories drift guard: the table
// must carry exactly the memories column set plus archived_at. It is lazy-safe
// by design — no shared column-const in prod, just a test-time comparison — so
// a future ALTER on memories that forgets its archived_memories mirror fails
// loud here instead of silently dropping a column at archive time. The guard
// runs against fresh AND migrated databases (SM-R8).
func assertColumnParity(t *testing.T, conn *sql.DB) {
	t.Helper()
	memCols := tableColumns(t, conn, "memories")
	archCols := tableColumns(t, conn, "archived_memories")

	want := make(map[string]bool, len(memCols)+1)
	for _, c := range memCols {
		want[c] = true
	}
	want["archived_at"] = true

	got := make(map[string]bool, len(archCols))
	for _, c := range archCols {
		got[c] = true
	}

	for c := range want {
		if !got[c] {
			t.Errorf("archived_memories missing column %q (present in memories ∪ {archived_at})", c)
		}
	}
	for c := range got {
		if !want[c] {
			t.Errorf("archived_memories has extra column %q not in memories ∪ {archived_at}", c)
		}
	}
}

// v6→v7 widens the three recency-serving indexes to 4 columns (ADR-0033):
// task_type/kind, created_at, and origin composites all end in
// `created_at DESC, id DESC` so the newest-first tiebreak never needs a temp
// B-tree sort.
func TestMigrate_V6toV7RedefinesIndexes(t *testing.T) {
	conn := loadFixture(t, "schema_v0.sql")
	if err := db.Migrate(conn); err != nil {
		t.Fatalf("Migrate: %v", err)
	}
	if got, want := userVersion(t, conn), db.CurrentSchemaVersion; got != want {
		t.Errorf("post-migrate user_version = %d, want %d", got, want)
	}
	got := indexDefs(t, conn)
	want := []string{
		"idx_memories_created_at(created_at DESC,id DESC)",
		"idx_memories_fingerprint(fingerprint)",
		"idx_memories_kind(kind)",
		"idx_memories_origin_created(origin,created_at DESC,id DESC)",
		"idx_memories_task_kind_created(task_type,kind,created_at DESC,id DESC)",
		// No idx_memories_task_type: task_type is the composite's leftmost
		// column, so idx_memories_task_kind_created already serves every
		// task_type-only lookup and the v6→v7 rung drops the standalone index.
		// idx_memories_kind stays — kind is the composite's SECOND column, so
		// no leftmost prefix covers a kind-only lookup.
	}
	if !equalStringSlices(got, want) {
		t.Errorf("migrated index definitions = %v, want %v", got, want)
	}
}

// v7→v8 adds authored_at, backfilled to created_at so no pre-existing row
// misreports its authoring date as the epoch.
func TestMigrate_V7toV8AddsAuthoredAtBackfillsCreatedAt(t *testing.T) {
	conn := newPreV1DB(t)
	now := int64(1000000)
	if _, err := conn.Exec(`
		INSERT INTO memories (id, session_id, task_type, kind, title, what, learned, tags, fingerprint, created_at, updated_at)
		VALUES ('mem_au', 'sess_au', 'crm', 'task_pattern', 't', 'w', 'l', '', 'fp_au', ?, ?)`,
		now, now); err != nil {
		t.Fatalf("seed row: %v", err)
	}
	if err := db.Migrate(conn); err != nil {
		t.Fatalf("Migrate: %v", err)
	}
	if !slices.Contains(tableColumns(t, conn, "memories"), "authored_at") {
		t.Fatal("migrated DB missing memories.authored_at")
	}
	if !slices.Contains(tableColumns(t, conn, "archived_memories"), "authored_at") {
		t.Fatal("migrated DB missing archived_memories.authored_at")
	}
	var authoredAt int64
	if err := conn.QueryRow(`SELECT authored_at FROM memories WHERE id = 'mem_au'`).Scan(&authoredAt); err != nil {
		t.Fatalf("read authored_at: %v", err)
	}
	if authoredAt != now {
		t.Errorf("backfilled authored_at = %d, want created_at %d", authoredAt, now)
	}
	if got, want := userVersion(t, conn), db.CurrentSchemaVersion; got != want {
		t.Errorf("post-migrate user_version = %d, want %d", got, want)
	}
}

